<?php
namespace App\Http\Controllers;
use App\Models\User; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class UsersController extends Controller {
 public function index(){return view('users.index',['users'=>User::latest()->paginate(15)]);}public function create(){return view('users.form');}public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users,email','password'=>'required|string|min:8','role'=>'required|in:admin,petugas,peminjam']);User::create($d);return redirect()->route('users.index')->with('sukses','User berhasil ditambahkan.');}public function edit(User $user){return view('users.form',compact('user'));}public function update(Request $r,User $user){$d=$r->validate(['name'=>'required|string|max:255','email'=>['required','email',Rule::unique('users')->ignore($user->id)],'password'=>'nullable|string|min:8','role'=>'required|in:admin,petugas,peminjam']);if(empty($d['password']))unset($d['password']);$user->update($d);return redirect()->route('users.index')->with('sukses','Data user diperbarui.');}public function destroy(User $user){abort_if((int)$user->id===(int)auth()->id(),403,'Anda tidak dapat menghapus akun yang sedang digunakan.');if($user->peminjamans()->exists())return back()->with('error','User masih memiliki data peminjaman.');$user->delete();return redirect()->route('users.index')->with('sukses','User dihapus.');}
}
